from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')

def one(old,new,label):
    global s
    c=s.count(old)
    if c!=1:
        raise SystemExit(f'{label}: expected 1, found {c}')
    s=s.replace(old,new,1)

one('<meta content="v1296 · ember-pending-upload-scope" name="fc-build"/>',
    '<meta content="v1297 · detail-video-layer-and-record-swipe-identity" name="fc-build"/>','build meta')
one('<meta content="Fixed Ember upload-status guidance so it only reports the signed-in member’s recent moderation job, never another competitor’s stale pending entry, and calls out unusually slow reviews accurately." name="fc-whatsnew"/>',
    '<meta content="Stopped Challenge Detail video previews from painting over challenger identity, and made Record-style audio entries visibly distinct while swiping by putting each challenger’s profile image on the record label." name="fc-whatsnew"/>','whatsnew')

old_video='''    } else if (entry.media_type === 'video' && entry.media_url) {\n      // Use poster+overlay so external URLs don't break — same as feed card\n      if (entry.poster_url) {\n        mediaHtml = `<div style="position:relative;cursor:pointer;" onclick="openEntryViewer('${entry.id}','${entry.challenge_id}')">\n          <video data-src="${escapeHtml(entry.media_url)}" ${_videoPosterAttr(entry.media_url, entry.poster_url)} muted playsinline preload="none" data-lazy-video style="width:100%;object-fit:cover;display:block;border-radius:8px;pointer-events:none;"></video>\n          <div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.25);border-radius:8px;font-size:52px;">▶</div>\n        </div>`;\n      } else {\n        // No poster — use autoplay muted video to show first frame (same as feed cards)\n        mediaHtml = `<div style="position:relative;cursor:pointer;" data-open-entry="${entry.id}" data-open-ch="${entry.challenge_id}">\n          <video data-src="${escapeHtml(entry.media_url)}" muted playsinline preload="none" data-lazy-video\n            style="width:100%;height:100%;object-fit:cover;display:block;border-radius:8px;pointer-events:none;"></video>\n          <div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;border-radius:8px;">\n            <div style="width:44px;height:44px;border-radius:50%;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;font-size:20px;">▶</div>\n          </div>\n        </div>`;\n      }\n'''
new_video='''    } else if (entry.media_type === 'video' && entry.media_url) {\n      // v1297 — Challenge Detail is a browse surface, not the deliberate video\n      // player. A real <video> element here could become its own accelerated\n      // Safari layer and paint over the challenger identity below it. Use the\n      // static Bunny poster as the preview and open the shared Entry Viewer for\n      // deliberate playback. Feed/Compete three-second previews are untouched.\n      if (entry.poster_url) {\n        mediaHtml = `<div class="fc-cd-video-poster-v1297" data-open-entry="${entry.id}" data-open-ch="${entry.challenge_id}" role="button" tabindex="0" aria-label="Open ${escapeHtml(entry.submitter?.name || 'competitor')} video">\n          <img src="${escapeHtml(entry.poster_url)}" alt="${escapeHtml(entry.submitter?.name || 'Competitor')} video preview" loading="lazy">\n          <div class="fc-cd-video-play-v1297" aria-hidden="true">▶</div>\n        </div>`;\n      } else {\n        mediaHtml = `<div class="fc-cd-video-poster-v1297 fc-cd-video-poster-empty-v1297" data-open-entry="${entry.id}" data-open-ch="${entry.challenge_id}" role="button" tabindex="0" aria-label="Open ${escapeHtml(entry.submitter?.name || 'competitor')} video">\n          <div class="fc-cd-video-play-v1297" aria-hidden="true">▶</div>\n        </div>`;\n      }\n'''
one(old_video,new_video,'challenge detail video preview')

old_decl="""  const IMG_URL = 'https://sioalvawzayfphwzqctq.supabase.co/storage/v1/object/public/challenge-media/Assets/fire.jpeg';\n  const rootClasses = `fcc-entry-media fcc-fire-eq eq-${style} fc-audio-mode-${mode}-v1123 fc-audio-layout-${audioLayoutV1201}-v1201${controls ? ' fc-audio-has-controls-v1123' : ''}`;\n"""
new_decl="""  const IMG_URL = 'https://sioalvawzayfphwzqctq.supabase.co/storage/v1/object/public/challenge-media/Assets/fire.jpeg';\n  // v1297 — Record style needed the same entry-to-entry identity cue the other\n  // audio presentations already get from their surrounding card. Put the\n  // challenger on the center label so a horizontal swipe visibly changes the\n  // record even when two audio files share identical artwork. Upload previews\n  // and non-competition audio fall back to the branded label.\n  const recordProfileV1297 = e?.submitter?.avatar\n    ? `<span class="fc-audio-record-profile-v1297">${avatarInner(e.submitter.avatar)}</span>`\n    : '<span class="fc-audio-record-brand-v1297"></span>';\n  const rootClasses = `fcc-entry-media fcc-fire-eq eq-${style} fc-audio-mode-${mode}-v1123 fc-audio-layout-${audioLayoutV1201}-v1201${controls ? ' fc-audio-has-controls-v1123' : ''}`;\n"""
one(old_decl,new_decl,'record profile declaration')
one('''        <div class="fc-audio-record-label-v1160"><span></span></div>''',
    '''        <div class="fc-audio-record-label-v1160">${recordProfileV1297}</div>''','record label markup')

addition='''\n<style id="fc-v1297-detail-video-record-swipe-css">\n/* v1297 — Challenge Detail video previews are static poster layers. The actual\n   video only exists in the shared Entry Viewer, so Safari cannot composite it\n   over the submitter name / record / action row underneath. */\n#challengeDetailSheet .cd-entry-media:has(.fc-cd-video-poster-v1297){\n  display:block!important;\n  width:100%!important;\n  max-height:min(60dvh,560px)!important;\n  overflow:hidden!important;\n  contain:paint!important;\n  isolation:isolate!important;\n  background:#000!important;\n}\n#challengeDetailSheet .fc-cd-video-poster-v1297{\n  position:relative!important;\n  width:100%!important;\n  max-height:min(60dvh,560px)!important;\n  overflow:hidden!important;\n  display:grid!important;\n  place-items:center!important;\n  background:#000!important;\n  cursor:pointer!important;\n}\n#challengeDetailSheet .fc-cd-video-poster-v1297>img{\n  width:100%!important;\n  height:auto!important;\n  max-height:min(60dvh,560px)!important;\n  object-fit:contain!important;\n  display:block!important;\n  background:#000!important;\n}\n#challengeDetailSheet .fc-cd-video-poster-empty-v1297{\n  aspect-ratio:16/9!important;\n  min-height:190px!important;\n}\n#challengeDetailSheet .fc-cd-video-play-v1297{\n  position:absolute!important;\n  left:50%!important;top:50%!important;transform:translate(-50%,-50%)!important;\n  width:58px!important;height:58px!important;border-radius:50%!important;\n  display:grid!important;place-items:center!important;\n  background:rgba(8,6,5,.66)!important;\n  border:1px solid rgba(255,255,255,.16)!important;\n  color:#fff!important;font-size:22px!important;line-height:1!important;\n  box-shadow:0 8px 26px rgba(0,0,0,.34)!important;\n  pointer-events:none!important;z-index:2!important;\n}\n#challengeDetailSheet .cd-entry:has(.fc-cd-video-poster-v1297) .cd-entry-body{\n  position:relative!important;\n  z-index:3!important;\n  background:linear-gradient(180deg,var(--surface),var(--bg-2))!important;\n  isolation:isolate!important;\n}\n.eq-vinyl .fc-audio-record-label-v1160>.fc-audio-record-profile-v1297{\n  width:82%!important;height:82%!important;display:grid!important;place-items:center!important;\n  overflow:hidden!important;border-radius:50%!important;background:none!important;\n  background-image:none!important;filter:none!important;box-shadow:0 0 0 2px rgba(255,210,157,.46),0 3px 10px rgba(0,0,0,.44)!important;\n  color:#fff!important;font-size:clamp(15px,4vw,24px)!important;line-height:1!important;\n}\n.eq-vinyl .fc-audio-record-label-v1160>.fc-audio-record-profile-v1297 img,\n.eq-vinyl .fc-audio-record-label-v1160>.fc-audio-record-profile-v1297 .avatar-img{\n  width:100%!important;height:100%!important;object-fit:cover!important;border-radius:50%!important;display:block!important;\n}\n.eq-vinyl .fc-audio-record-label-v1160>.fc-audio-record-brand-v1297{\n  width:72%!important;height:72%!important;display:block!important;\n}\n</style>\n<script>window.FC_V1297_VALIDATION={build:'v1297',challengeDetailUsesStaticVideoPoster:true,noDetailVideoLayerOverIdentity:true,feedVideoPreviewPreserved:true,recordLabelUsesChallengerAvatar:true,recordOuterGeometryPreserved:true,v1296EmberPendingScopePreserved:true};</script>\n'''
if s.count('</body>')!=1:
    raise SystemExit('body marker')
s=s.replace('</body>',addition+'</body>',1)
p.write_text(s,encoding='utf-8')
